require_once __DIR__.'/../includes/bootstrap.php';require_role(['customer']);if(empty($_SESSION['cart'])){header('Location: cart.php');exit;}if(empty($_SESSION['checkout_details'])){header('Location: checkout.php');exit;}if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$_SESSION['payment_method']=($_SESSION['checkout_details']['fulfillment']??'delivery')==='delivery'?'cash_on_delivery':'cash_at_collection';header('Location: review.php');exit;}
$cart=$_SESSION['cart'];$ids=array_map('intval',array_keys($cart));$marks=implode(',',array_fill(0,count($ids),'?'));$st=$pdo->prepare("SELECT product_id,price FROM products WHERE product_id IN ($marks)");$st->execute($ids);$subtotal=0;foreach($st as $p)$subtotal+=(int)$cart[$p['product_id']]*(float)$p['price'];$delivery=($_SESSION['checkout_details']['fulfillment']??'delivery')==='delivery'?150:0;$pageTitle='Payment | Redline Royale';$pageClass='payment-page';include __DIR__.'/../includes/header.php';
?><div class="page-kicker">PAYMENT</div><h1 class="page-heading">Choose a payment method</h1><form class="payment-card" method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><h2>Cash on delivery</h2><p>Pay in cash when your order arrives.</p><p>For collection: pay at the selected pickup point.</p><div class="payment-notice">No card details are requested or stored.</div><h3>Order total &nbsp; Rs. <?=number_format($subtotal+$delivery,2)?></h3><div class="checkout-return-actions"><a href="checkout.php">Edit delivery details</a><button type="submit">Continue to review</button></div></form><?php include __DIR__.'/../includes/footer.php';?>
